def main():
    coverage=json.loads((AUDIT/'FOCUSED_SPELL_SOURCE_PREPARATION_COVERAGE.json').read_text(encoding='utf-8'))
    assert len(coverage['cohortFiles'])==22 and coverage['distinctPreparedPendingSpellIds']==287
    remaining=set(coverage['remainingUnpreparedSpellIds'])
    prepare(prefix='ILLUSION_NECROMANCY_RANK6',title='Remaining rank-six Illusion and Necromancy source audit',questions=QUESTIONS,
        selector=lambda r:r['id'] in remaining and r['operational'] is None and bool(set(r['schools']) & {'Illusion','Necromancy'}) and min(v['rank'] for v in r['classAccess'].values())==6,
        expected_count=13,question_prefix='IN6',prior_files=coverage['cohortFiles'],expected_prior_count=287,
        counterpart_ids=['minor-illusion','sleep','vampiric-touch','sense-undead','dominate-beast'],
        pending_ids=['phantasmal-killer','phantom-swarm','mental-prison','mass-suggestion','summon-death-knight','danse-macabre','enervation'],
        expected_class_mentions=0,
        extra_excerpts={
            'CREATURE_LIFECYCLE_PLAYTEST.md':None,
            'HEALING_DEATH_PLAYTEST.md':['Distinct life operations','Damage quantities and resolution','Ordinary healing arithmetic','Recovery gates, triggers and loops'],
            'ENCHANTMENT_CONTROL_INTEGRATION_PLAYTEST.md':None,
            'TRANSFORMATION_SPELL_PLAYTEST.md':['Identity, attack statistics and equipment','Endings, switching, suppression and geometry'],
            'CONDITIONS_PLAYTEST.md':['Unconscious'],
        },
        introduction='Thirteen remaining rank-six identities retain fourteen book/Core placements. True Seeing preserves both school-specific clauses; Soul Cage,Mental Prison and Mass Suggestion remain in the prior Enchantment cohort without duplication. Recurring psychic/necrotic damage keeps conflicting Instantaneous metadata. All four named Create Undead outcomes remain required unresolved profiles. The Soul Wraith name grants no soul-capture ontology. No cosmology,spell approval or external-game import occurs.',
        future_dispatch='Prepared only during the active Skinning source review. Before dispatch,rebase creature,illusion,control,healing,body and source-profile dependencies. Supply actual named undead profiles or identify missing evidence explicitly. Source decisions precede full authored cards and separate exact review; cosmology remains post-verified-push.')

if __name__=='__main__': main()
